insert into public.products
  (id, name, slug, description, short_description, category, price, image_url, size, colour_name, colour_hex, finish, coverage, stock_quantity, is_active, is_featured)
values
  ('a1000000-0000-4000-8000-000000000001', 'Velvet Matt Interior Emulsion', 'velvet-matt-harmattan-mist-4l', 'A rich, chalky matt emulsion with exceptional opacity and depth of colour. Low-odour, quick-drying and washable once cured, it hides minor surface imperfections and gives living rooms, bedrooms and hallways a soft, light-diffusing finish.', 'Chalky, light-diffusing matt in a soft warm white.', 'interior', 18500.00, '/images/products/velvet-matt-harmattan-mist-4l.svg', '4 L', 'Harmattan Mist', '#EDE6DA', 'Matt', '12–14 m² per litre per coat', 48, true, true),
  ('a1000000-0000-4000-8000-000000000002', 'Velvet Matt Interior Emulsion', 'velvet-matt-harmattan-mist-20l', 'A rich, chalky matt emulsion with exceptional opacity and depth of colour. Low-odour, quick-drying and washable once cured, it hides minor surface imperfections and gives living rooms, bedrooms and hallways a soft, light-diffusing finish.', 'Contractor pack of our best-selling warm white matt.', 'interior', 82000.00, '/images/products/velvet-matt-harmattan-mist-20l.svg', '20 L', 'Harmattan Mist', '#EDE6DA', 'Matt', '12–14 m² per litre per coat', 16, true, false),
  ('a1000000-0000-4000-8000-000000000003', 'Silk Sheen Interior Emulsion', 'silk-sheen-clay-rose-4l', 'A mid-sheen emulsion that balances elegance with durability. The silk finish reflects light gently, resists scuffs and wipes clean, making it ideal for kitchens, corridors and children''s rooms.', 'Wipeable mid-sheen in a muted, sun-warmed pink.', 'interior', 21000.00, '/images/products/silk-sheen-clay-rose-4l.svg', '4 L', 'Clay Rose', '#D9A99A', 'Silk', '11–13 m² per litre per coat', 22, true, true),
  ('a1000000-0000-4000-8000-000000000004', 'Silk Sheen Interior Emulsion', 'silk-sheen-lagoon-teal-4l', 'A mid-sheen emulsion that balances elegance with durability. The silk finish reflects light gently, resists scuffs and wipes clean, making it ideal for kitchens, corridors and children''s rooms.', 'Deep, calming teal for feature walls and studies.', 'interior', 21000.00, '/images/products/silk-sheen-lagoon-teal-4l.svg', '4 L', 'Lagoon Teal', '#2F5F5C', 'Silk', '11–13 m² per litre per coat', 14, true, false),
  ('a1000000-0000-4000-8000-000000000005', 'Velvet Matt Interior Emulsion', 'velvet-matt-sage-grove-4l', 'A rich, chalky matt emulsion with exceptional opacity and depth of colour. Low-odour, quick-drying and washable once cured, it hides minor surface imperfections and gives living rooms, bedrooms and hallways a soft, light-diffusing finish.', 'Soft botanical green that pairs with timber and brass.', 'interior', 18500.00, '/images/products/velvet-matt-sage-grove-4l.svg', '4 L', 'Sage Grove', '#9AA88F', 'Matt', '12–14 m² per litre per coat', 31, true, true),
  ('a1000000-0000-4000-8000-000000000006', 'Velvet Matt Interior Emulsion', 'velvet-matt-iroko-earth-4l', 'A rich, chalky matt emulsion with exceptional opacity and depth of colour. Low-odour, quick-drying and washable once cured, it hides minor surface imperfections and gives living rooms, bedrooms and hallways a soft, light-diffusing finish.', 'Warm terracotta inspired by laterite soil and clay pots.', 'interior', 18500.00, '/images/products/velvet-matt-iroko-earth-4l.svg', '4 L', 'Iroko Earth', '#B8623F', 'Matt', '12–14 m² per litre per coat', 9, true, false),
  ('a1000000-0000-4000-8000-000000000007', 'Washable Matt Interior Emulsion', 'washable-matt-charcoal-night-4l', 'Our most durable matt. Built for high-traffic spaces and dramatic feature walls, this emulsion withstands repeated scrubbing without burnishing, so dark colours stay uniform for years.', 'Dramatic near-black with a scrub-resistant matt finish.', 'interior', 22500.00, '/images/products/washable-matt-charcoal-night-4l.svg', '4 L', 'Charcoal Night', '#2E2E33', 'Matt', '12–14 m² per litre per coat', 4, true, false),
  ('a1000000-0000-4000-8000-000000000008', 'WeatherShield Exterior Emulsion', 'weathershield-pure-white-20l', 'A premium exterior emulsion engineered for the Nigerian climate. Formulated with UV-stable pigments and a breathable acrylic binder, it resists fading, algae and heavy harmattan dust while letting moisture escape from the wall.', 'UV-stable, algae-resistant exterior white in a contractor pack.', 'exterior', 96000.00, '/images/products/weathershield-pure-white-20l.svg', '20 L', 'Pure White', '#F7F6F2', 'Smooth matt', '10–12 m² per litre per coat', 12, true, true),
  ('a1000000-0000-4000-8000-000000000009', 'WeatherShield Exterior Emulsion', 'weathershield-sandstone-4l', 'A premium exterior emulsion engineered for the Nigerian climate. Formulated with UV-stable pigments and a breathable acrylic binder, it resists fading, algae and heavy harmattan dust while letting moisture escape from the wall.', 'Warm neutral that flatters both modern and colonial façades.', 'exterior', 24000.00, '/images/products/weathershield-sandstone-4l.svg', '4 L', 'Sandstone', '#D4C4A8', 'Smooth matt', '10–12 m² per litre per coat', 27, true, false),
  ('a1000000-0000-4000-8000-000000000010', 'WeatherShield Exterior Emulsion', 'weathershield-slate-grey-4l', 'A premium exterior emulsion engineered for the Nigerian climate. Formulated with UV-stable pigments and a breathable acrylic binder, it resists fading, algae and heavy harmattan dust while letting moisture escape from the wall.', 'Architectural grey for contemporary exteriors and boundary walls.', 'exterior', 24000.00, '/images/products/weathershield-slate-grey-4l.svg', '4 L', 'Slate Grey', '#6E7178', 'Smooth matt', '10–12 m² per litre per coat', 18, true, false),
  ('a1000000-0000-4000-8000-000000000011', 'Elastomeric Exterior Coating', 'elastomeric-exterior-pure-white-20l', 'A thick, highly flexible acrylic coating that stretches with the building and seals hairline cracks against driving rain. Recommended for parapets, exposed elevations and older rendered walls.', 'Flexible, waterproofing membrane paint that bridges hairline cracks.', 'exterior', 145000.00, '/images/products/elastomeric-exterior-pure-white-20l.svg', '20 L', 'Pure White', '#F7F6F2', 'Low sheen', '4–6 m² per litre per coat', 6, true, false),
  ('a1000000-0000-4000-8000-000000000012', 'Ceiling White Flat Emulsion', 'ceiling-white-flat-20l', 'A dead-flat ceiling emulsion that hides roller marks and surface irregularities. Low-splatter formulation keeps floors clean and the bright white brightens rooms without glare.', 'Non-reflective, splatter-resistant ceiling white.', 'ceiling', 58000.00, '/images/products/ceiling-white-flat-20l.svg', '20 L', 'Ceiling White', '#FBFBF9', 'Dead flat', '12–14 m² per litre per coat', 20, true, false),
  ('a1000000-0000-4000-8000-000000000013', 'Ceiling White Flat Emulsion', 'ceiling-white-flat-4l', 'A dead-flat ceiling emulsion that hides roller marks and surface irregularities. Low-splatter formulation keeps floors clean and the bright white brightens rooms without glare.', 'Non-reflective ceiling white for single rooms.', 'ceiling', 13500.00, '/images/products/ceiling-white-flat-4l.svg', '4 L', 'Ceiling White', '#FBFBF9', 'Dead flat', '12–14 m² per litre per coat', 40, true, false),
  ('a1000000-0000-4000-8000-000000000014', 'Universal Wall Primer & Sealer', 'universal-wall-primer-4l', 'A water-based primer-sealer that binds dusty surfaces, evens out porosity and improves topcoat adhesion. One coat before any PrimeCoat emulsion means truer colour and fewer finishing coats.', 'Seals new plaster and old paint for an even, long-lasting topcoat.', 'primer', 14000.00, '/images/products/universal-wall-primer-4l.svg', '4 L', null, null, 'Matt', '10–12 m² per litre per coat', 55, true, true),
  ('a1000000-0000-4000-8000-000000000015', 'Alkali-Resisting Primer', 'alkali-resisting-primer-20l', 'Essential on new cement render, concrete and block work. This solvent-free primer blocks alkali salts that would otherwise cause saponification, blistering and colour fade.', 'Protects topcoats from alkaline attack on fresh cement render.', 'primer', 62000.00, '/images/products/alkali-resisting-primer-20l.svg', '20 L', null, null, 'Matt', '9–11 m² per litre per coat', 10, true, false),
  ('a1000000-0000-4000-8000-000000000016', 'Wood & Metal Primer', 'wood-metal-primer-grey-1l', 'A quick-drying primer-undercoat for bare and previously painted timber and ferrous metal. Provides a uniform grey base for gloss and satin enamels.', 'Fast-drying undercoat for doors, frames, gates and railings.', 'primer', 7800.00, '/images/products/wood-metal-primer-grey-1l.svg', '1 L', 'Primer Grey', '#9C9EA3', 'Matt', '12–14 m² per litre per coat', 36, true, false),
  ('a1000000-0000-4000-8000-000000000017', 'Premium High Gloss Enamel', 'high-gloss-brilliant-white-4l', 'A hard-wearing solvent-based enamel with brilliant flow and levelling. Dries to a mirror finish that resists chipping and yellowing. Ideal for doors, window frames, skirtings and metalwork.', 'Mirror-like, non-yellowing gloss for doors, trims and furniture.', 'gloss', 26500.00, '/images/products/high-gloss-brilliant-white-4l.svg', '4 L', 'Brilliant White', '#FFFFFF', 'High gloss', '14–16 m² per litre per coat', 25, true, true),
  ('a1000000-0000-4000-8000-000000000018', 'Premium High Gloss Enamel', 'high-gloss-signal-red-1l', 'A hard-wearing solvent-based enamel with brilliant flow and levelling. Dries to a mirror finish that resists chipping and yellowing.', 'Vivid, durable red for gates, doors and accents.', 'gloss', 8200.00, '/images/products/high-gloss-signal-red-1l.svg', '1 L', 'Signal Red', '#C8322B', 'High gloss', '14–16 m² per litre per coat', 12, true, false),
  ('a1000000-0000-4000-8000-000000000019', 'Satin Enamel', 'satin-enamel-jet-black-1l', 'A tough satin-finish enamel that hides brush marks and surface wear better than full gloss. Excellent on balustrades, window grilles and furniture.', 'Soft-sheen black for railings, frames and furniture.', 'gloss', 8200.00, '/images/products/satin-enamel-jet-black-1l.svg', '1 L', 'Jet Black', '#111113', 'Satin', '14–16 m² per litre per coat', 0, true, false),
  ('a1000000-0000-4000-8000-000000000020', 'Stucco Textured Wall Finish', 'stucco-textured-natural-sand-20kg', 'A ready-mixed acrylic texture coating that can be trowelled, combed or stippled into a range of decorative patterns. Weather-resistant and ideal for pillars, fences and accent walls.', 'Trowel-applied decorative finish for feature and exterior walls.', 'textured', 68000.00, '/images/products/stucco-textured-natural-sand-20kg.svg', '20 kg', 'Natural Sand', '#D8CBB4', 'Textured', '1.5–2 kg per m²', 8, true, false),
  ('a1000000-0000-4000-8000-000000000021', 'Fine Textured Coat', 'fine-textured-coat-pebble-4l', 'A sand-filled emulsion that rolls on like paint but cures to a subtle, uniform texture. Perfect for hiding patched or uneven walls without full re-plastering.', 'Roller-applied fine texture that disguises uneven plaster.', 'textured', 19000.00, '/images/products/fine-textured-coat-pebble-4l.svg', '4 L', 'Pebble', '#BEB7AA', 'Fine texture', '4–6 m² per litre', 15, true, false),
  ('a1000000-0000-4000-8000-000000000022', 'Clear Polyurethane Varnish', 'clear-polyurethane-varnish-satin-1l', 'A tough, non-yellowing polyurethane varnish that protects timber from moisture, scratches and daily wear while letting the grain show through.', 'Protective satin clear coat for doors, floors and furniture.', 'wood_finish', 9500.00, '/images/products/clear-polyurethane-varnish-satin-1l.svg', '1 L', 'Clear', null, 'Satin', '14–16 m² per litre per coat', 28, true, false),
  ('a1000000-0000-4000-8000-000000000023', 'Interior Wood Stain', 'wood-stain-dark-mahogany-1l', 'A penetrating, fade-resistant stain that colours timber evenly without masking the grain. Finish with Clear Polyurethane Varnish for protection.', 'Rich, even colour for doors, panelling and furniture.', 'wood_finish', 8900.00, '/images/products/wood-stain-dark-mahogany-1l.svg', '1 L', 'Dark Mahogany', '#5C2E22', 'Penetrating stain', '16–18 m² per litre', 19, true, false),
  ('a1000000-0000-4000-8000-000000000024', 'Anti-Rust Metal Enamel', 'anti-rust-metal-enamel-graphite-1l', 'A rust-inhibiting enamel that can be applied directly to sound or lightly rusted steel without a separate primer. Weatherproof and resistant to chipping.', 'Direct-to-metal protection for gates, railings and tanks.', 'metal_finish', 9800.00, '/images/products/anti-rust-metal-enamel-graphite-1l.svg', '1 L', 'Graphite', '#45484D', 'Satin', '12–14 m² per litre per coat', 24, true, false),
  ('a1000000-0000-4000-8000-000000000025', 'Painter''s Masking Tape', 'painters-masking-tape-48mm', 'A medium-tack crepe tape that holds firmly for up to 7 days and removes cleanly without residue or paint lift.', 'Clean-release tape for sharp lines on walls and trims.', 'accessories', 2400.00, '/images/products/painters-masking-tape-48mm.svg', '48 mm × 50 m', null, null, null, null, 120, true, false),
  ('a1000000-0000-4000-8000-000000000026', 'Sandpaper Assortment Pack', 'sandpaper-assortment-pack', 'Ten aluminium-oxide sheets across 80, 120, 180 and 240 grit for stripping, keying and finishing. Cuts quickly and resists clogging.', 'Mixed 80–240 grit sheets for preparation and between-coat sanding.', 'accessories', 3200.00, '/images/products/sandpaper-assortment-pack.svg', '10 sheets', null, null, null, null, 75, true, false),
  ('a1000000-0000-4000-8000-000000000027', 'Paint Tray with Liner', 'paint-tray-with-liner-230mm', 'A rigid polypropylene tray with a ribbed loading ramp and a disposable liner, sized for 230 mm rollers.', 'Deep-well tray with a disposable liner for fast colour changes.', 'accessories', 4500.00, '/images/products/paint-tray-with-liner-230mm.svg', '230 mm', null, null, null, null, 42, true, false),
  ('a1000000-0000-4000-8000-000000000028', 'Cotton Drop Cloth', 'cotton-drop-cloth-3-6x2-7m', 'A reusable 8 oz cotton canvas drop cloth. Unlike plastic sheeting it does not slip or pool paint, and it folds away for the next job.', 'Heavy canvas floor protection that stays put and absorbs drips.', 'accessories', 6800.00, '/images/products/cotton-drop-cloth-3-6x2-7m.svg', '3.6 × 2.7 m', null, null, null, null, 30, true, false),
  ('a1000000-0000-4000-8000-000000000029', 'Microfibre Roller Sleeve', 'microfibre-roller-sleeve-230mm-2pk', 'Twelve-millimetre-pile microfibre sleeves that hold more paint, release it evenly and leave no lint. Suitable for all PrimeCoat emulsions on smooth to lightly textured walls.', 'Lint-free sleeves for a smooth, even emulsion finish.', 'tools', 5600.00, '/images/products/microfibre-roller-sleeve-230mm-2pk.svg', '230 mm · 2-pack', null, null, null, null, 64, true, true),
  ('a1000000-0000-4000-8000-000000000030', 'Roller Frame & Extension Pole Set', 'roller-frame-extension-pole-set', 'A heavy-duty 230 mm cage frame with a twist-lock aluminium pole extending from 1.2 to 2.4 metres. Fits all standard roller sleeves.', 'Reach ceilings and high walls without a ladder.', 'tools', 12500.00, '/images/products/roller-frame-extension-pole-set.svg', '230 mm frame · 1.2–2.4 m pole', null, null, null, null, 18, true, false),
  ('a1000000-0000-4000-8000-000000000031', 'Professional Brush Set', 'professional-brush-set-3pc', 'Tapered synthetic filaments that hold a sharp edge for cutting in and release paint smoothly with both water- and solvent-based coatings. Beech handles, stainless ferrules.', 'Three synthetic-bristle brushes for cutting-in and trim work.', 'tools', 9900.00, '/images/products/professional-brush-set-3pc.svg', '25 / 50 / 75 mm', null, null, null, null, 3, true, false),
  ('a1000000-0000-4000-8000-000000000032', 'Paint Mixer Drill Attachment', 'paint-mixer-drill-attachment', 'A zinc-plated helical mixing paddle for cordless or corded drills. Ensures pigments are fully dispersed before application so colour is consistent from first wall to last.', 'Blends 20 L drums to a uniform colour in under a minute.', 'tools', 7500.00, '/images/products/paint-mixer-drill-attachment.svg', 'Fits 10 mm chuck', null, null, null, null, 0, true, false)
